module D = Hm_declarative
module V = Verified_hm
module C = Hm_checked_elaboration

let elaborate (term : D.term @ immutable) =
  if D.scoped_term D.Z term then
    let answer = V.infer term in
    V.elaborate term (borrow_ answer)
  else failwith "unscoped fixture"

let () =
  let var = D.Bound D.Z in
  let outer = D.Bound (D.S D.Z) in
  let id = D.Lambda var in
  let term = D.Let (id, D.Let (D.Apply (var, D.Truth),
    D.Apply (outer, outer))) in
  (match elaborate term with
   | None -> failwith "polymorphic identity rejected"
   | Some checked ->
     match C.derivation checked with
     | D.Let_binding (_, _, D.Let_binding (_,
         D.Application (_, D.Variable (D.Argument (D.Boolean, D.No_arguments)), _),
         D.Application (_, D.Variable (D.Argument (D.Function _, D.No_arguments)), _))) -> ()
     | _ -> failwith "missing distinct per-use instantiations");
  (match elaborate (D.Apply (D.Truth, D.Truth)) with
   | None -> () | Some _ -> failwith "ill-typed application accepted");
  (match elaborate (D.Lambda (D.Apply (var, var))) with
   | None -> () | Some _ -> failwith "infinite type accepted")
